import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Day04 · Runtime and executor convergence","description":"","frontmatter":{"title":"Day04 · Runtime and executor convergence","outline":false},"headers":[],"relativePath":"en/log/day-04.md","filePath":"en/log/day-04.md","lastUpdated":1794050510000}'),n={name:"en/log/day-04.md"};function r(i,t,s,c,l,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<p>On 2026-11-06 Hearth grew from the stage-one MVP into a full local Agent OS. That day 102 commits touched 432 files (+35,228/−4,327), moving the chat-first interface, native agent runtime, four model protocols, sources and document extraction, local outbox, Windows desktop helper, proactive service, memory, method evolution, incremental sync, leases, kill switch, encrypted backup, health maintenance, and redacted diagnostics into running code with automated tests.</p><p>On 2026-11-07, Day04 continued by converging the executor layer onto one path: 42 commits touched 165 files (+28,030/−1,845), adding a shared seven-executor registry, a SQLite model registry, a task-level context ledger with executor handoff, failure diagnosis and routing fallback, and a settings page reorganised into executors, models, context, and data. Qoder, WorkBuddy, Kimi, and DeepSeek Harness joined the unified adapter layer, and the transitional ZCode integration was removed.</p><p>The two days did not treat &quot;the page exists&quot; as closure: server, API, projection, executor boundary, and tests landed together. The suite grew from 51 tests to 54 test files and 296 tests; <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run docs:build</code> all passed. Phases 2–6 still count as partial, not because code is missing, but because real accounts, real devices, and long-running acceptance are still outstanding.</p><h2 id="what-shipped-on-2026-11-06" tabindex="-1">What shipped on 2026-11-06 <a class="header-anchor" href="#what-shipped-on-2026-11-06" aria-label="Permalink to &quot;What shipped on 2026-11-06&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Chat-first interface</td><td>Rebuilt the web app around conversation, with tasks, proposals, approvals, and artifacts organised around the thread</td></tr><tr><td>Native agent runtime</td><td>Single-agent tool loop, four budget classes, tool permissions, checkpoints, wait-for-input and resume, and recovery of missing artifacts</td></tr><tr><td>Four model protocols</td><td>OpenAI Chat, OpenAI Responses, Anthropic Messages, and Gemini unified as streaming agent turns</td></tr><tr><td>Two executors</td><td><code>native</code> and <code>codex</code> sit side by side; executor identity is written into the run manifest and failures never switch silently</td></tr><tr><td>Sources and documents</td><td>Local files, knowledge base, web pages, and TXT/Markdown/CSV/JSON/HTML/PDF/DOCX/XLSX extraction with source entries</td></tr><tr><td>Local outbox</td><td>Drafts, one-time approval, write to the local outbox after approval, and stored receipts</td></tr><tr><td>Windows desktop</td><td>Six-digit pairing, per-capability approval, observation, pause/takeover/hand-back, low-risk input, UIA invoke, and UWP window attribution</td></tr><tr><td>Proactive service</td><td>Six trigger classes, a proactive inbox, accept/ignore/snooze/convert-to-task, and an attention budget</td></tr><tr><td>Memory and methods</td><td>Memory candidates, recall, correction, conflict, forgetting, and export; method candidates, trial evidence, evaluation, promotion, rejection, and rollback</td></tr><tr><td>Multi-device and safety</td><td>Incremental event sync, peer authentication, task leases with epoch fencing, device revocation, token rotation, and a global kill switch</td></tr><tr><td>Backup and operations</td><td>AES-256-GCM encrypted backup, rollback restore, health snapshots, periodic maintenance, and redacted diagnostics</td></tr></tbody></table><h2 id="executor-and-context-convergence-on-2026-11-07" tabindex="-1">Executor and context convergence on 2026-11-07 <a class="header-anchor" href="#executor-and-context-convergence-on-2026-11-07" aria-label="Permalink to &quot;Executor and context convergence on 2026-11-07&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Seven-executor registry</td><td><code>native</code>, <code>codex</code>, and <code>deepseek-harness</code> are first-class; <code>hermes</code>, <code>qoder</code>, <code>workbuddy</code>, and <code>kimi</code> are external; all share launch resolution, health probes, managed installs, model bindings, context collection, and one settings surface</td></tr><tr><td>Unified model registry</td><td><code>model_profiles</code> and <code>executor_model_bindings</code> live in SQLite; legacy <code>model-settings.json</code> / <code>executor-settings.json</code> are imported at startup with backups under <code>.hearth/backups/legacy-dev/</code>; API keys are AES-256-GCM encrypted and masked in the UI</td></tr><tr><td>Protocol constraints</td><td>Codex is fixed to OpenAI Responses; local addresses stay out of unified model management; non-native executors must bind a model explicitly; the server enforces executor/protocol compatibility</td></tr><tr><td>Context ledger</td><td>Every executor writes messages, tool calls, results, checkpoints, and notices to <code>context_items</code>; <code>executor_event_id</code> deduplicates, large bodies go to <code>.hearth/context/blobs/</code>, and task summaries live in <code>task_context_state</code></td></tr><tr><td>Failure diagnosis and handoff</td><td>Rules first separate executor faults from non-executor faults; the current Hearth chat model diagnoses; full-permission low-risk runs switch automatically, while approval mode only asks whether to switch; at most two handoffs by default, each carrying <code>context_watermark_seq</code></td></tr><tr><td>Routing and selection</td><td>One executor picker replaces the chat toggles; the conversation-level choice outranks the global default; unavailable or incapable choices fall back to the task-matched executor; task-like requests honour the explicit selection without a router model</td></tr><tr><td>Settings and data</td><td>Settings is reorganised into executors, models, context, and data; model registry and storage information are exposed over APIs; SQLite schema advances to 10; Codex uses the configured home and injected environment, and health checks report the managed binding without rewriting config</td></tr><tr><td>Executor adapters</td><td>DeepSeek Harness runs through its official SDK/JSON-RPC; Hermes moves to the unified external adapter and resumes the previous CLI session; Qoder, WorkBuddy, and Kimi adapters are added; ZCode is removed</td></tr><tr><td>Documentation and UI</td><td>New storage and context architecture guide in both languages, updated executor docs and README; the app shell fits the viewport, settings readability improves, and chat streams model reasoning separately from the answer</td></tr></tbody></table><h2 id="verification-baseline" tabindex="-1">Verification baseline <a class="header-anchor" href="#verification-baseline" aria-label="Permalink to &quot;Verification baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Tests</td><td><code>npm test</code> passed 54 test files and 296 tests</td></tr><tr><td>Types</td><td><code>npm run typecheck</code> passed</td></tr><tr><td>Web build</td><td><code>npm run build</code> passed</td></tr><tr><td>Docs build</td><td><code>npm run docs:build</code> passed</td></tr><tr><td>Real tasks</td><td>Stage-one acceptance still stands: 15 tasks ran, 13 passed; the T07/T08 boundaries are unchanged</td></tr><tr><td>Evidence rule</td><td>Code closure was not written up as real acceptance; external comments and desktop actions were not described as completed</td></tr></tbody></table><blockquote><p>This log records implementation and internal verification, not a v1.0 release. Real accounts, real devices, long-running operation, and failure drills for phases 2–6 remain governed by <a href="/hearth-os/en/delivery/status.html">delivery status</a>.</p></blockquote><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><h3 id="_2026-11-06-102-commits-selected" tabindex="-1">2026-11-06 (102 commits, selected) <a class="header-anchor" href="#_2026-11-06-102-commits-selected" aria-label="Permalink to &quot;2026-11-06 (102 commits, selected)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>a0544fd</code></td><td>JasonBuildAI</td><td>Added the Simple Pro read model to prepare aggregated task, approval, and artifact views for the chat-first interface; 8 files (+729/−21).</td></tr><tr><td><code>b748d02</code></td><td>JasonBuildAI</td><td>Converged the interface on the Simple Pro structure and removed the older complex control-plane layout; 32 files (+2,970/−1,360).</td></tr><tr><td><code>3aca641</code></td><td>JasonBuildAI</td><td>Rebuilt the web app as a chat-first interface organised around conversation, tasks, proposals, and approvals; 9 files (+1,288/−357).</td></tr><tr><td><code>8d28901</code></td><td>JasonBuildAI</td><td>Added the source registry store, recording source type, status, read time, and errors; 3 files (+198/−1).</td></tr><tr><td><code>cec6d41</code></td><td>JasonBuildAI</td><td>Added source-reading APIs for local files, knowledge base, and web sources, with incremental refresh; 5 files (+735/−2).</td></tr><tr><td><code>b408eb3</code></td><td>JasonBuildAI</td><td>Added document extraction for TXT, Markdown, CSV, JSON, HTML, PDF, DOCX, and XLSX, including page, sheet, and range records; 6 files (+3,461/−74).</td></tr><tr><td><code>d458bd3</code></td><td>JasonBuildAI</td><td>Added a source picker to the new-task flow so ready source entries can be attached to a task; 4 files (+180/−6).</td></tr><tr><td><code>ae5bf0f</code></td><td>JasonBuildAI</td><td>Added the outbox draft projection, showing drafts, submission status, and receipts; 3 files (+152/−2).</td></tr><tr><td><code>b820dca</code></td><td>JasonBuildAI</td><td>Added outbox draft APIs for editing, saving, discarding, and submitting for approval; 6 files (+551/−1).</td></tr><tr><td><code>f1558a9</code></td><td>JasonBuildAI</td><td>Wrote approved drafts to the local outbox with stored receipts, and synchronised draft state on rejection or expiry; 4 files (+408/−4).</td></tr><tr><td><code>5b6e50f</code></td><td>JasonBuildAI</td><td>Added the Windows desktop helper with window observation, focus, click, text input, keys, and UIA actions; 1 file (+358).</td></tr><tr><td><code>34877a0</code></td><td>JasonBuildAI</td><td>Bound observation frames to the target application and rejected silently treating the host window as the approved app; 3 files (+92/−15).</td></tr><tr><td><code>97d0f07</code></td><td>JasonBuildAI</td><td>Resolved UWP host windows to their UIA child process and mapped them to the approved app, such as CalculatorApp to calculator; 1 file (+109/−17).</td></tr><tr><td><code>119b67f</code></td><td>JasonBuildAI</td><td>Recorded UWP and UIA isolation verification, including calculator invoke and the observe → act → auto-observe chain; 2 files (+6/−6).</td></tr><tr><td><code>11a1e60</code></td><td>JasonBuildAI</td><td>Added the proactive trigger engine covering deadline windows, failure or recoverability, uncertain results, pending approval, new sources, and queue backlog; 5 files (+1,144/−1).</td></tr><tr><td><code>66ee76c</code></td><td>JasonBuildAI</td><td>Added the proactive inbox and attention budget with accept, ignore, snooze, and convert-to-task; 8 files (+624/−1).</td></tr><tr><td><code>21d1592</code></td><td>JasonBuildAI</td><td>Added memory core and recall, recording provenance, confidence, sensitivity, version, and recall audits; 7 files (+1,170/−3).</td></tr><tr><td><code>ac92758</code></td><td>JasonBuildAI</td><td>Added memory browse, correction, conflict, and forgetting; forgetting redacts historical versions and recall audits; 6 files (+599/−1).</td></tr><tr><td><code>11b0307</code></td><td>JasonBuildAI</td><td>Added memory-poisoning boundary tests so memory cannot act as an instruction that widens permissions; 1 file (+21).</td></tr><tr><td><code>b6b3f63</code></td><td>JasonBuildAI</td><td>Added the method evaluation engine, recording baseline and trial success rate, duration, tokens, and approval count; 5 files (+788).</td></tr><tr><td><code>0e3a35f</code></td><td>JasonBuildAI</td><td>Added method evolution browsing with candidate generation, evaluation, promotion, rejection, and rollback; 6 files (+493/−1).</td></tr><tr><td><code>724e784</code></td><td>JasonBuildAI</td><td>Added incremental event sync and peer authentication, pulling by sequence, deduplicating, and rebuilding projections; 7 files (+816/−5).</td></tr><tr><td><code>24c2ea4</code></td><td>JasonBuildAI</td><td>Put task execution under TTL, owner, and epoch leases; expired takeover advances the epoch and stale-owner writes are rejected; 7 files (+391/−7).</td></tr><tr><td><code>e70b0d3</code></td><td>JasonBuildAI</td><td>Added the global kill switch, device revocation, token rotation, and safety audit; 14 files (+678/−22).</td></tr><tr><td><code>44f58b9</code></td><td>JasonBuildAI</td><td>Added AES-256-GCM encrypted backup and rollback restore, validating schema, user_version, and integrity_check; 16 files (+1,160/−22).</td></tr><tr><td><code>b3cffeb</code></td><td>JasonBuildAI</td><td>Added runtime health snapshots, periodic maintenance, and redacted diagnostics, marking degraded when maintenance fails; 15 files (+974/−29).</td></tr><tr><td><code>42d8827</code></td><td>JasonBuildAI</td><td>Recorded phase 4–6 delivery status, separating implemented, verified, and still-open items; 13 files (+124/−12).</td></tr><tr><td><code>32f0b0d</code></td><td>JasonBuildAI</td><td>Unified four model protocols: OpenAI Chat, OpenAI Responses, Anthropic Messages, and Gemini; 5 files (+665/−74).</td></tr><tr><td><code>581bc44</code></td><td>JasonBuildAI</td><td>Let chat answer material questions first instead of dispatching every input directly as a task; 3 files (+61/−19).</td></tr><tr><td><code>e4eefbb</code></td><td>JasonBuildAI</td><td>Added the single-agent loop with budgets and checkpoints; 5 files (+396).</td></tr><tr><td><code>99392ea</code></td><td>JasonBuildAI</td><td>Added permission-bound built-in tools for read/write, search, shell, web, asking the user, and completion; 2 files (+589).</td></tr><tr><td><code>9a37e78</code></td><td>JasonBuildAI</td><td>Added executor, permission, budget, and checkpoint contracts; 1 file (+58).</td></tr><tr><td><code>375ff8d</code></td><td>JasonBuildAI</td><td>Added the executor registry so native and codex are peers; 1 file (+33).</td></tr><tr><td><code>bbbbfab</code></td><td>JasonBuildAI</td><td>Added the native agent executor adapter connecting the runtime to the scheduler; 3 files (+168).</td></tr><tr><td><code>5f5009a</code></td><td>JasonBuildAI</td><td>Required tasks needing network or engineering-workspace permission to produce a chat proposal before dispatch; 2 files (+79/−5).</td></tr><tr><td><code>6b4295d</code></td><td>JasonBuildAI</td><td>Collected answers inline when a task waits for input, then resumed execution; 2 files (+53/−4).</td></tr><tr><td><code>c776d2c</code></td><td>JasonBuildAI</td><td>Recorded the native runtime closure, explaining executor, protocol, tools, budgets, and recovery boundaries; 2 files (+24/−2).</td></tr><tr><td><code>b5a785f</code></td><td>JasonBuildAI</td><td>Derived health expectations from the current schema version to stop test drift after upgrades; 2 files (+4/−4).</td></tr></tbody></table><h3 id="_2026-11-07-42-commits" tabindex="-1">2026-11-07 (42 commits) <a class="header-anchor" href="#_2026-11-07-42-commits" aria-label="Permalink to &quot;2026-11-07 (42 commits)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>e5b27b6</code></td><td>JasonBuildAI</td><td>Streamed model reasoning separately from answer text so thinking does not leak into the deliverable; 6 files (+209/−40).</td></tr><tr><td><code>6142c20</code></td><td>JasonBuildAI</td><td>Rebuilt the README and documentation site for Day04, including the homepage, delivery route, and capability status; 99 files (+2,890/−1,970).</td></tr><tr><td><code>f1cfe5d</code></td><td>JasonBuildAI</td><td>Restored the original site structure and updated delivery content, rebuilding stage and sub-stage pages; 97 files (+2,131/−2,434).</td></tr><tr><td><code>e6ac426</code></td><td>JasonBuildAI</td><td>Added the unified context ledger and executor handoff across collection, projection, summaries, metrics, diagnosis, and <code>handoffs</code>; 65 files (+9,461/−528).</td></tr><tr><td><code>5457227</code></td><td>JasonBuildAI</td><td>Added the shared seven-executor registry with executor identity, tier, and capabilities in shared types; 19 files (+304/−101).</td></tr><tr><td><code>24902d5</code></td><td>JasonBuildAI</td><td>Added generic launch resolution and health probes across user paths, managed installs, global installs, and <code>PATH</code>; 6 files (+744/−19).</td></tr><tr><td><code>c793b26</code></td><td>JasonBuildAI</td><td>Added managed executor install jobs with status, logs, and errors; 6 files (+438/−3).</td></tr><tr><td><code>65a35bd</code></td><td>JasonBuildAI</td><td>Added Qoder, WorkBuddy, ZCode, and Kimi adapters reusing local logins and streaming events; 5 files (+987/−31).</td></tr><tr><td><code>9a524ac</code></td><td>JasonBuildAI</td><td>Made routing honour the preferred executor instead of always overriding it with the task-matched one; 3 files (+71/−2).</td></tr><tr><td><code>af1f02a</code></td><td>JasonBuildAI</td><td>Unified executor installation, health, paths, concurrency, and model bindings in settings; 5 files (+593/−140).</td></tr><tr><td><code>4e05832</code></td><td>JasonBuildAI</td><td>Replaced the chat executor toggles with a single picker; 3 files (+95/−59).</td></tr><tr><td><code>3be7808</code></td><td>JasonBuildAI</td><td>Fell back to the task-matched executor when the selected one is unavailable or lacks capability; 3 files (+49/−3).</td></tr><tr><td><code>1460c4e</code></td><td>JasonBuildAI</td><td>Documented the unified executor registry and the extension constraints; 3 files (+75/−3).</td></tr><tr><td><code>0205c88</code></td><td>JasonBuildAI</td><td>Removed the ZCode integration, its settings, adapters, and tests; 21 files (+29/−246).</td></tr><tr><td><code>da9f006</code></td><td>JasonBuildAI</td><td>Moved executor model bindings and task status into SQLite; 13 files (+797/−28).</td></tr><tr><td><code>d89cddc</code></td><td>JasonBuildAI</td><td>Added the DeepSeek Harness SDK/JSON-RPC adapter with native tools, session resume, and full event streams; 10 files (+11,294/−803).</td></tr><tr><td><code>24882cc</code></td><td>JasonBuildAI</td><td>Made the Codex executor honour the configured <code>CODEX_HOME</code> and injected environment instead of assuming the default directory; 3 files (+11/−3).</td></tr><tr><td><code>35986e6</code></td><td>JasonBuildAI</td><td>Wired the SQLite model registry into server routes and settings APIs; 6 files (+251/−25).</td></tr><tr><td><code>f79aff1</code></td><td>JasonBuildAI</td><td>Imported legacy JSON settings into SQLite at startup, backing them up under <code>.hearth/backups/legacy-dev/</code> and recording the migration; 7 files (+435/−26).</td></tr><tr><td><code>5067f3d</code></td><td>JasonBuildAI</td><td>Routed Hermes through the unified external executor adapter while keeping launch and event parsing; 5 files (+126/−94).</td></tr><tr><td><code>e6376fc</code></td><td>JasonBuildAI</td><td>Detected DeepSeek through SDK runtime markers and ignored non-result attempt events; 3 files (+41/−4).</td></tr><tr><td><code>d72d5cf</code></td><td>JasonBuildAI</td><td>Required non-native executors to bind a model explicitly instead of inheriting the chat model; 1 file (+2/−4).</td></tr><tr><td><code>67109b7</code></td><td>JasonBuildAI</td><td>Resumed the previous Hermes CLI session to reduce repeated context; 3 files (+43/−10).</td></tr><tr><td><code>b7c9031</code></td><td>JasonBuildAI</td><td>Added executor failure diagnosis and cross-executor handoff with fallback order, diagnosis summaries, and handoff bundles; 4 files (+282/−50).</td></tr><tr><td><code>819f1e2</code></td><td>JasonBuildAI</td><td>Added constraint tests enforcing Codex Responses and keeping local models out of unified management; 1 file (+64).</td></tr><tr><td><code>e66948a</code></td><td>JasonBuildAI</td><td>Exposed model registry and storage APIs to the web settings page; 2 files (+63).</td></tr><tr><td><code>44aaa70</code></td><td>JasonBuildAI</td><td>Reorganised settings into executors, models, context, and data; 2 files (+1,009/−380).</td></tr><tr><td><code>7fe45dc</code></td><td>JasonBuildAI</td><td>Added the Chinese storage and context architecture guide covering SQLite, blobs, the model registry, and handoff; 1 file (+134).</td></tr><tr><td><code>3fe318d</code></td><td>JasonBuildAI</td><td>Added the English storage and context architecture guide; 1 file (+134).</td></tr><tr><td><code>d37d298</code></td><td>JasonBuildAI</td><td>Documented executor tiers, model bindings, handoff, and shared context in Chinese; 1 file (+61/−16).</td></tr><tr><td><code>d372405</code></td><td>JasonBuildAI</td><td>Mirrored the tier, model binding, and handoff guidance in English; 1 file (+61/−16).</td></tr><tr><td><code>5ad480a</code></td><td>JasonBuildAI</td><td>Linked the storage architecture from the design indexes; 3 files (+6/−2).</td></tr><tr><td><code>b6f39e7</code></td><td>JasonBuildAI</td><td>Described executor tiers, the model registry, and SQLite storage in the README; 1 file (+16/−9).</td></tr><tr><td><code>8126587</code></td><td>JasonBuildAI</td><td>Aligned the Chinese README overview with executors and storage; 1 file (+28/−5).</td></tr><tr><td><code>2ef7837</code></td><td>JasonBuildAI</td><td>Refreshed the design module map in the appendix; 2 files (+8/−8).</td></tr><tr><td><code>cab8c8d</code></td><td>JasonBuildAI</td><td>Refreshed the verified test count in the README; 2 files (+4/−4).</td></tr><tr><td><code>09d0a7c</code></td><td>JasonBuildAI</td><td>Fitted the app shell to the viewport and fixed scrolling and layout in narrow windows; 2 files (+37/−11).</td></tr><tr><td><code>f0ec945</code></td><td>JasonBuildAI</td><td>Improved settings readability with spacing, grouping, and type hierarchy; 1 file (+90).</td></tr><tr><td><code>cadbbf7</code></td><td>JasonBuildAI</td><td>Honoured the conversation-selected executor for task-like requests; 4 files (+131/−8).</td></tr><tr><td><code>e198a27</code></td><td>JasonBuildAI</td><td>Derived executor readiness from runtime health in the web UI; 2 files (+64/−11).</td></tr><tr><td><code>bb4e18b</code></td><td>JasonBuildAI</td><td>Kept task routing deterministic when no router model is configured; 2 files (+14/−2).</td></tr><tr><td><code>872e847</code></td><td>JasonBuildAI</td><td>Made Codex health report the managed binding without rewriting the config file; 1 file (+8/−7).</td></tr></tbody></table><h2 id="boundaries-and-next-step" tabindex="-1">Boundaries and next step <a class="header-anchor" href="#boundaries-and-next-step" aria-label="Permalink to &quot;Boundaries and next step&quot;">​</a></h2><ul><li>The phase 2–6 code closures run, but real mail/calendar accounts, high-risk desktop actions, the phone entry point, memory production comparisons, two-device switching, and long-running operation are not yet accepted.</li><li>All seven executors are registered and covered by automated tests, but real Qoder, WorkBuddy, and Kimi logins, long-running DeepSeek Harness operation, cross-executor consistency, and handoff drills are not yet accepted.</li><li>The unified model registry and context ledger now live in SQLite (schema 10), and legacy settings migrate with backups; capacity, retention, and cross-device context sync still lack long-running data.</li><li>Handoff defaults to at most two attempts and one retry per executor; diagnosis accuracy and automatic-switch safety under real faults still need comparison data.</li><li>The chat-first primary navigation only exposes chat, tasks, devices, and settings; memory, methods, sync, safety, and operations have APIs and page components that are not yet wired back into primary navigation.</li><li>The next stage does not add more pages. It closes real evidence item by item along the <a href="/hearth-os/en/delivery/">delivery route</a>.</li></ul>',17)])])}const f=e(n,[["render",r]]);export{p as __pageData,f as default};
